import { db } from "./db";

// First-party event stream. Every product analytic — the activation funnel,
// retention cohorts, per-user journeys, attribution, the admin overview — is a
// query over this one table rather than its own bespoke tracking.
//
// Two rules keep it useful:
//
// 1. NAMES ARE A CLOSED SET. Free-text event names rot within weeks: three
//    spellings of the same thing, and every funnel query silently undercounts.
//    EVENTS below is the whole vocabulary; adding one is a deliberate edit.
// 2. PROPS ARE SMALL AND NON-PII. Ids, counts, short enum-ish strings. Never
//    prompt bodies, never generated content, never anything that would make
//    this table a second copy of user data with different retention rules.

// NOTE: every name here must actually be emitted somewhere. Two acquisition
// names (landing.viewed, landing.prompt_submitted) were removed on 2026-08-22
// because nothing fired them — they needed a client-side beacon endpoint that
// was never built. Aspirational names are not free: the privacy policy is
// written from this list, so a name that never fires makes the policy describe
// collection that doesn't happen. Add them back together with the beacon, and
// update app/legal/privacy in the same change.
export const EVENTS = {
  // Activation — the path the North Star measures.
  signedUp: "user.signed_up",
  projectCreated: "project.created",
  // Churn signal, and the counterweight to projectCreated: a funnel that only
  // counts creations reads as growth while people are deleting everything.
  projectDeleted: "project.deleted",
  buildStarted: "build.started",
  buildSucceeded: "build.succeeded",
  buildFailed: "build.failed",
  // Explicit thumbs up/down on a finished build — the only signal here that is
  // a direct statement of satisfaction rather than an inference from behaviour.
  buildRated: "build.rated",
  sitePublished: "project.published",

  // Monetization.
  creditsExhausted: "credits.exhausted",
  spendCapReached: "credits.cap_reached",
  checkoutStarted: "billing.checkout_started",
  creditsPurchased: "billing.credits_purchased",
} as const;

export type EventName = (typeof EVENTS)[keyof typeof EVENTS];

/**
 * The North Star: a user reaching their first PUBLISHED build. Not first
 * signup, not first generation — the moment the product delivered the thing
 * it promises, a real site at a real URL.
 */
export const NORTH_STAR: EventName = EVENTS.sitePublished;

type Props = Record<string, string | number | boolean | null | undefined>;

/**
 * Record an event. Deliberately fire-and-forget: analytics must never fail a
 * user's request or add latency to a build. A dropped event is a small gap in
 * a dashboard; a thrown one would be a failed generation.
 */
export function track(name: EventName, opts: { userId?: string | null; props?: Props } = {}): void {
  void db.event
    .create({
      data: {
        name,
        userId: opts.userId ?? null,
        props: opts.props ? (JSON.parse(JSON.stringify(opts.props)) as object) : undefined,
      },
    })
    .catch((err) => {
      // Log and move on — see above.
      console.error(`[events] failed to record ${name}:`, err);
    });
}

export type FunnelStep = { step: string; event: EventName; users: number; pctOfPrevious: number | null };

/**
 * Activation funnel: signup → first project → first successful build → first
 * publish, counted in DISTINCT USERS rather than events. Counting events would
 * let one enthusiastic user look like retention.
 */
export async function activationFunnel(sinceDays = 30): Promise<FunnelStep[]> {
  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);

  const steps: { step: string; event: EventName }[] = [
    { step: "Signed up", event: EVENTS.signedUp },
    { step: "Created a project", event: EVENTS.projectCreated },
    { step: "Built successfully", event: EVENTS.buildSucceeded },
    { step: "Published a site", event: EVENTS.sitePublished },
  ];

  const out: FunnelStep[] = [];
  let previous: number | null = null;

  for (const s of steps) {
    const rows = await db.event.findMany({
      where: { name: s.event, createdAt: { gte: since }, userId: { not: null } },
      distinct: ["userId"],
      select: { userId: true },
    });
    const users = rows.length;
    out.push({
      ...s,
      users,
      pctOfPrevious: previous === null || previous === 0 ? null : Math.round((users / previous) * 1000) / 10,
    });
    previous = users;
  }

  return out;
}

/**
 * Green-build-first-try: the share of successful builds that compiled with no
 * repair attempt. A roadmap kill-criterion — the jump to backend work is meant
 * to be gated on it, and nothing measured it before `Build.repairAttempts`.
 */
export async function greenBuildRate(sinceDays = 30): Promise<{
  succeeded: number;
  firstTry: number;
  rate: number | null;
}> {
  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
  const where = { status: "SUCCEEDED", createdAt: { gte: since } };

  const [succeeded, firstTry] = await Promise.all([
    db.build.count({ where }),
    db.build.count({ where: { ...where, repairAttempts: 0 } }),
  ]);

  return {
    succeeded,
    firstTry,
    rate: succeeded === 0 ? null : Math.round((firstTry / succeeded) * 1000) / 10,
  };
}

/**
 * What people ask for AFTER a build, ranked. This is the learning-mode
 * scoreboard: the top bucket is, in aggregate, what the first generation gets
 * wrong most often, and therefore what the next prompt change should target.
 *
 * Buckets come from a heuristic (lib/feedback-intent.ts) and are only
 * meaningful in aggregate — see the caveats in that file.
 */
export async function followUpIntents(
  sinceDays = 30,
): Promise<{ intent: string; count: number; pct: number }[]> {
  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);

  const rows = await db.event.findMany({
    where: { name: EVENTS.buildStarted, createdAt: { gte: since } },
    select: { props: true },
  });

  const counts = new Map<string, number>();
  for (const row of rows) {
    const intent = (row.props as { intent?: unknown } | null)?.intent;
    // Absent on first builds, which have no follow-up to classify.
    if (typeof intent !== "string") continue;
    counts.set(intent, (counts.get(intent) ?? 0) + 1);
  }

  const total = [...counts.values()].reduce((a, b) => a + b, 0);
  return [...counts.entries()]
    .map(([intent, count]) => ({
      intent,
      count,
      pct: total === 0 ? 0 : Math.round((count / total) * 1000) / 10,
    }))
    .sort((a, b) => b.count - a.count);
}

/** Thumbs up/down on finished builds. */
export async function buildRatings(sinceDays = 30): Promise<{
  up: number;
  down: number;
  rated: number;
  satisfaction: number | null;
}> {
  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);

  const rows = await db.event.findMany({
    where: { name: EVENTS.buildRated, createdAt: { gte: since } },
    select: { props: true },
  });

  let up = 0;
  let down = 0;
  for (const row of rows) {
    const rating = (row.props as { rating?: unknown } | null)?.rating;
    if (rating === "up") up++;
    else if (rating === "down") down++;
  }

  const rated = up + down;
  return { up, down, rated, satisfaction: rated === 0 ? null : Math.round((up / rated) * 1000) / 10 };
}

import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";

export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  const user = await getCurrentUser();
  if (!user || user.role !== "ADMIN") redirect("/dashboard");

  return <>{children}</>;
}
=====USERS PAGE=====
import Link from "next/link";
import { notFound } from "next/navigation";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import {
  Empty,
  StatTile,
  TableFrame,
  Th,
  formatDate,
  formatUsd,
  truncate,
} from "./ui";

export const dynamic = "force-dynamic";

const PAGE_SIZE = 25;

type SortKey = "recent" | "oldest" | "email" | "projects";

/**
 * Only DATABASE-NATIVE sorts are offered. Balance, lifetime spend and build
 * count are all derived from other tables and are computed per PAGE (see
 * below) — sorting the page by one of them would silently sort 25 arbitrary
 * rows rather than the whole table, which is worse than not offering it.
 */
const SORTS: Record<SortKey, { label: string; orderBy: Prisma.UserOrderByWithRelationInput }> = {
  recent: { label: "Newest", orderBy: { createdAt: "desc" } },
  oldest: { label: "Oldest", orderBy: { createdAt: "asc" } },
  email: { label: "Email", orderBy: { email: "asc" } },
  projects: { label: "Projects", orderBy: { projects: { _count: "desc" } } },
};

function isSortKey(v: unknown): v is SortKey {
  return typeof v === "string" && v in SORTS;
}

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

function href(params: { q: string; sort: SortKey; page: number }): string {
  const sp = new URLSearchParams();
  if (params.q) sp.set("q", params.q);
  if (params.sort !== "recent") sp.set("sort", params.sort);
  if (params.page > 1) sp.set("page", String(params.page));
  const qs = sp.toString();
  return qs ? `/admin/users?${qs}` : "/admin/users";
}

// ── Per-page rollups ──────────────────────────────────────────────────────
// Everything below is keyed by userId and fetched for the CURRENT PAGE ONLY,
// in a fixed number of queries (6) regardless of how many users are on it.
// No query ever runs inside a loop over users.

type BalanceRow = { userId: string; balanceAfter: number };

type BuildRollupRow = {
  userId: string;
  builds: number;
  succeeded: number;
  failed: number;
  costMicros: bigint;
  creditsCharged: bigint;
  lastBuildAt: Date | null;
};

type Rollup = {
  balance: number;
  netDelta: number;
  spent: number;
  builds: number;
  succeeded: number;
  failed: number;
  costMicros: number;
  creditsCharged: number;
  lastBuildAt: Date | null;
};

const EMPTY_ROLLUP: Rollup = {
  balance: 0,
  netDelta: 0,
  spent: 0,
  builds: 0,
  succeeded: 0,
  failed: 0,
  costMicros: 0,
  creditsCharged: 0,
  lastBuildAt: null,
};

export default async function AdminUsersPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
  // is not an authorization boundary on its own (it does not re-render on
  // every navigation within the section). Same idiom as app/admin/page.tsx:
  // 404 rather than redirect, so a non-admin learns nothing about this path.
  if (!(await getAdminUser())) notFound();

  const sp = await searchParams;
  const q = first(sp.q).trim();
  const sortRaw = first(sp.sort);
  const sort: SortKey = isSortKey(sortRaw) ? sortRaw : "recent";
  const pageRaw = Number.parseInt(first(sp.page), 10);
  const page = Number.isFinite(pageRaw) && pageRaw > 0 ? pageRaw : 1;

  // Search by email, by display name, or by pasting a raw user id straight out
  // of a log line or a support ticket.
  const where: Prisma.UserWhereInput = q
    ? {
        OR: [
          { email: { contains: q, mode: "insensitive" } },
          { name: { contains: q, mode: "insensitive" } },
          { id: q },
        ],
      }
    : {};

  const [total, users] = await Promise.all([
    db.user.count({ where }),
    db.user.findMany({
      where,
      // `id` breaks ties so pagination is stable when timestamps collide.
      orderBy: [SORTS[sort].orderBy, { id: "asc" }],
      skip: (page - 1) * PAGE_SIZE,
      take: PAGE_SIZE,
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        createdAt: true,
        spendCapCredits: true,
        _count: { select: { projects: true } },
      },
    }),
  ]);

  const ids = users.map((u) => u.id);

  // ── Balance for many users, without one query each ────────────────────
  // lib/credits.ts `getBalance` reads `balanceAfter` off the user's NEWEST
  // ledger row. Postgres does that for a whole set of users in one pass with
  // DISTINCT ON: sort by (userId, createdAt DESC, id DESC) and keep the first
  // row per userId. `id` is the tiebreak so two rows written inside the same
  // millisecond still resolve deterministically to the same row Prisma's
  // findFirst would have picked.
  const balanceRows = ids.length
    ? await db.$queryRaw<BalanceRow[]>`
        SELECT DISTINCT ON (l."userId") l."userId", l."balanceAfter"
        FROM "CreditLedger" l
        WHERE l."userId" IN (${Prisma.join(ids)})
        ORDER BY l."userId", l."createdAt" DESC, l."id" DESC`
    : [];

  // Build has no userId — it hangs off Project — so the per-user build
  // rollup is one grouped join rather than a per-user count.
  const buildRows = ids.length
    ? await db.$queryRaw<BuildRollupRow[]>`
        SELECT p."userId",
               COUNT(*)::int AS "builds",
               COUNT(*) FILTER (WHERE b."status" = 'SUCCEEDED')::int AS "succeeded",
               COUNT(*) FILTER (WHERE b."status" = 'FAILED')::int AS "failed",
               COALESCE(SUM(b."costMicros"), 0)::bigint AS "costMicros",
               COALESCE(SUM(b."creditsCharged"), 0)::bigint AS "creditsCharged",
               MAX(b."createdAt") AS "lastBuildAt"
        FROM "Build" b
        JOIN "Project" p ON p."id" = b."projectId"
        WHERE p."userId" IN (${Prisma.join(ids)})
        GROUP BY p."userId"`
    : [];

  const [spentRows, netRows] = ids.length
    ? await Promise.all([
        db.creditLedger.groupBy({
          by: ["userId"],
          where: { userId: { in: ids }, delta: { lt: 0 } },
          _sum: { delta: true },
        }),
        // The ledger is append-only and starts at zero, so the sum of every
        // delta MUST equal the newest row's balanceAfter. Cheap to check here
        // (one grouped query for the page) and the only way to notice a
        // ledger that has drifted before a customer does.
        db.creditLedger.groupBy({
          by: ["userId"],
          where: { userId: { in: ids } },
          _sum: { delta: true },
        }),
      ])
    : [[], []];

  const rollups = new Map<string, Rollup>(ids.map((id) => [id, { ...EMPTY_ROLLUP }]));
  for (const r of balanceRows) {
    const u = rollups.get(r.userId);
    if (u) u.balance = r.balanceAfter;
  }
  for (const r of buildRows) {
    const u = rollups.get(r.userId);
    if (!u) continue;
    u.builds = Number(r.builds);
    u.succeeded = Number(r.succeeded);
    u.failed = Number(r.failed);
    u.costMicros = Number(r.costMicros);
    u.creditsCharged = Number(r.creditsCharged);
    u.lastBuildAt = r.lastBuildAt;
  }
  for (const r of spentRows) {
    const u = rollups.get(r.userId);
    // Deltas are negative for spend; show it as a positive number.
    if (u) u.spent = Math.abs(r._sum.delta ?? 0);
  }
  for (const r of netRows) {
    const u = rollups.get(r.userId);
    if (u) u.netDelta = r._sum.delta ?? 0;
  }

  const pageCount = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const drifted = [...rollups.values()].filter((r) => r.balance !== r.netDelta).length;

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← kodely admin
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">Users</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          Read-only. Per-customer credits, builds and cost — the view that answers a billing
          email.
        </p>
      </div>

      <div className="mb-6 grid grid-cols-2 gap-4 sm:grid-cols-4">
        <StatTile label="Users matching" value={total} />
        <StatTile label="On this page" value={users.length} />
        <StatTile label="Page" value={`${page} / ${pageCount}`} />
        <StatTile
          label="Ledger drift"
          value={drifted}
          tone={drifted > 0 ? "warn" : undefined}
          hint="balanceAfter vs sum of deltas, this page"
        />
      </div>

      <form method="get" action="/admin/users" className="mb-6 flex flex-wrap items-center gap-2">
        <input
          type="search"
          name="q"
          defaultValue={q}
          placeholder="Search email, name or user id"
          aria-label="Search users"
          className="w-full max-w-sm rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus:border-black/30 dark:border-white/10 dark:placeholder:text-white/40 dark:focus:border-white/30"
        />
        <select
          name="sort"
          defaultValue={sort}
          aria-label="Sort users"
          className="rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none dark:border-white/10"
        >
          {(Object.keys(SORTS) as SortKey[]).map((k) => (
            <option key={k} value={k}>
              {SORTS[k].label}
            </option>
          ))}
        </select>
        <button
          type="submit"
          className="rounded-xl border border-black/10 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
        >
          Search
        </button>
        {q ? (
          <Link
            href="/admin/users"
            className="text-sm text-black/50 underline-offset-4 hover:underline dark:text-white/50"
          >
            Clear
          </Link>
        ) : null}
      </form>

      {users.length === 0 ? (
        <Empty>{q ? `No users match “${truncate(q, 40)}”.` : "No users yet."}</Empty>
      ) : (
        <TableFrame>
          <thead>
            <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
              <Th>Email</Th>
              <Th>Signed up</Th>
              <Th>Role</Th>
              <Th align="right">Projects</Th>
              <Th align="right">Builds</Th>
              <Th align="right">Balance</Th>
              <Th align="right">Spent</Th>
              <Th align="right">Cost</Th>
            </tr>
          </thead>
          <tbody className="divide-y divide-black/10 dark:divide-white/10">
            {users.map((u) => {
              const r = rollups.get(u.id) ?? EMPTY_ROLLUP;
              const drift = r.balance !== r.netDelta;
              return (
                <tr key={u.id}>
                  <td className="max-w-xs px-4 py-2">
                    <Link
                      href={`/admin/users/${u.id}`}
                      className="font-medium underline-offset-4 hover:underline"
                    >
                      {truncate(u.email, 44)}
                    </Link>
                    {u.name ? (
                      <div className="text-xs text-black/50 dark:text-white/50">
                        {truncate(u.name, 44)}
                      </div>
                    ) : null}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
                    {formatDate(u.createdAt)}
                  </td>
                  <td className="px-4 py-2 text-black/70 dark:text-white/70">
                    {u.role === "ADMIN" ? (
                      <span className="font-medium">ADMIN</span>
                    ) : (
                      <span className="text-black/50 dark:text-white/50">{u.role}</span>
                    )}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {u._count.projects}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {r.builds}
                    {r.builds > 0 ? (
                      <span className="ml-2 text-xs">
                        <span className="text-emerald-600 dark:text-emerald-400">{r.succeeded}</span>
                        <span className="text-black/30 dark:text-white/30"> / </span>
                        <span className="text-red-600 dark:text-red-400">{r.failed}</span>
                      </span>
                    ) : null}
                  </td>
                  <td className="whitespace-nowrap px-4 py-2 text-right tabular-nums">
                    <span className={r.balance === 0 ? "text-red-600 dark:text-red-400" : ""}>
                      {r.balance}
                    </span>
                    {drift ? (
                      <span
                        className="ml-1 text-amber-600 dark:text-amber-500"
                        title={`Ledger drift: newest balanceAfter is ${r.balance} but deltas sum to ${r.netDelta}`}
                      >
                        !
                      </span>
                    ) : null}
                    {u.spendCapCredits !== null ? (
                      <div className="text-xs text-black/50 dark:text-white/50">
                        cap {u.spendCapCredits}
                      </div>
                    ) : null}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {r.spent}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {formatUsd(r.costMicros, 4)}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </TableFrame>
      )}

      <div className="mt-4 flex items-center justify-between text-sm">
        <span className="text-black/50 dark:text-white/50">
          {total === 0
            ? "0 users"
            : `${(page - 1) * PAGE_SIZE + 1}–${Math.min(page * PAGE_SIZE, total)} of ${total}`}
        </span>
        <span className="flex gap-2">
          {page > 1 ? (
            <Link
              href={href({ q, sort, page: page - 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Previous
            </Link>
          ) : null}
          {page < pageCount ? (
            <Link
              href={href({ q, sort, page: page + 1 })}
              className="rounded-xl border border-black/10 px-3 py-1.5 hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/5"
            >
              Next
            </Link>
          ) : null}
        </span>
      </div>

      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
        Balance is the newest ledger row&apos;s balanceAfter, matching lib/credits.ts. Spent is the
        sum of negative deltas. Cost is real model spend across every build on the user&apos;s
        projects, charged or not — failed builds cost us money and are never billed.
      </p>
    </div>
  );
}

import { randomBytes, scrypt as _scrypt, timingSafeEqual, createHash } from "node:crypto";
import { promisify } from "node:util";
import { cookies } from "next/headers";
import { db } from "./db";

const scrypt = promisify(_scrypt) as (
  password: string,
  salt: Buffer,
  keylen: number,
) => Promise<Buffer>;

const SESSION_COOKIE = "kodely_session";
const SESSION_DAYS = 30;

export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `scrypt$${salt.toString("hex")}$${key.toString("hex")}`;
}

export async function verifyPassword(password: string, stored: string): Promise<boolean> {
  const [scheme, saltHex, keyHex] = stored.split("$");
  if (scheme !== "scrypt" || !saltHex || !keyHex) return false;
  const key = await scrypt(password, Buffer.from(saltHex, "hex"), 64);
  const expected = Buffer.from(keyHex, "hex");
  if (key.length !== expected.length) return false;
  return timingSafeEqual(key, expected);
}

// Session tokens are stored hashed, so a database read never yields a usable cookie.
function hashToken(token: string) {
  return createHash("sha256").update(token).digest("hex");
}

export async function createSession(userId: string) {
  const token = randomBytes(32).toString("base64url");
  const expiresAt = new Date(Date.now() + SESSION_DAYS * 86_400_000);
  await db.session.create({ data: { userId, tokenHash: hashToken(token), expiresAt } });

  const jar = await cookies();
  jar.set(SESSION_COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    expires: expiresAt,
  });
}

export async function destroySession() {
  const jar = await cookies();
  const token = jar.get(SESSION_COOKIE)?.value;
  if (token) await db.session.deleteMany({ where: { tokenHash: hashToken(token) } });
  jar.delete(SESSION_COOKIE);
}

export async function getCurrentUser() {
  const jar = await cookies();
  const token = jar.get(SESSION_COOKIE)?.value;
  if (!token) return null;

  const session = await db.session.findUnique({
    where: { tokenHash: hashToken(token) },
    include: { user: true },
  });
  if (!session || session.expiresAt < new Date()) return null;
  return session.user;
}

export async function requireUser() {
  const user = await getCurrentUser();
  if (!user) throw new Error("UNAUTHENTICATED");
  return user;
}

/**
 * Signed in AND role === "ADMIN". Returns null otherwise — callers decide
 * between a 404 and a redirect rather than getting a thrown error.
 *
 * app/admin/layout.tsx already gates the admin section, and that check is the
 * real one. This exists so each admin PAGE and API route can assert the same
 * thing itself: Next's own guidance is not to treat a layout as the sole
 * authorization boundary, since layouts don't re-render on every navigation
 * within a section and route handlers don't sit under them at all. Belt and
 * braces on a page showing cost, margin, and customer prompts.
 */
export async function getAdminUser() {
  const user = await getCurrentUser();
  return user && user.role === "ADMIN" ? user : null;
}

import type { ReactNode } from "react";

// Presentational helpers shared by the user list and the user detail page.
// Not a route — only page/layout/route filenames are routable — so this file
// is safe to sit inside app/admin/users/.
//
// Everything here mirrors the vocabulary already established in
// app/admin/page.tsx (rounded-xl hairline borders, text-sm, tabular-nums on
// every figure, monochrome except for status semantics) so the two pages read
// as one panel rather than two.

export function formatUsd(micros: number, decimals = 2): string {
  return `$${(micros / 1_000_000).toFixed(decimals)}`;
}

/** Whole-second UTC stamp, matching the recent-builds table on /admin. */
export function formatDateTime(d: Date): string {
  return d.toISOString().replace("T", " ").slice(0, 19);
}

export function formatDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export function truncate(text: string, max = 60): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

export function statusClass(status: string): string {
  if (status === "SUCCEEDED") return "text-emerald-600 dark:text-emerald-400";
  if (status === "FAILED") return "text-red-600 dark:text-red-400";
  return "text-black/40 dark:text-white/40";
}

/**
 * CreditLedger.reason is free text and carries three different encodings —
 * plain words ("build", "signup_grant"), a Stripe session id, and the social
 * reward state machine (app/api/rewards/_lib.ts) whose reason string embeds an
 * identity HASH. Rendering those raw would put a 64-char hex blob in the
 * middle of a billing statement, so decode them into something a human can
 * scan. The raw string is still shown on hover via `title`.
 */
export function reasonLabel(reason: string): string {
  if (reason === "build") return "Build";
  if (reason === "signup_grant") return "Signup grant";
  if (reason.startsWith("stripe:")) return "Credit purchase";
  if (reason.startsWith("reward:")) {
    const parts = reason.split(":");
    const platform = parts[1] ?? "";
    const name = platform ? platform[0].toUpperCase() + platform.slice(1) : "Social";
    return parts[2] === "pending" ? `${name} reward (pending)` : `${name} reward`;
  }
  return reason.replace(/_/g, " ");
}

export function StatTile({
  label,
  value,
  hint,
  tone,
}: {
  label: string;
  value: ReactNode;
  hint?: ReactNode;
  tone?: "warn";
}) {
  return (
    <div className="rounded-xl border border-black/10 p-4 dark:border-white/10">
      <div className="text-xs text-black/50 dark:text-white/50">{label}</div>
      <div
        className={`mt-1 text-xl font-semibold tabular-nums ${
          tone === "warn" ? "text-amber-600 dark:text-amber-500" : ""
        }`}
      >
        {value}
      </div>
      {hint ? <div className="mt-1 text-xs text-black/50 dark:text-white/50">{hint}</div> : null}
    </div>
  );
}

export function Panel({
