// Kodely — Phase 1 data model.
// Principles baked in here (see the Kodely board):
//  - every generation is a Build row with real token counts, so cost per build is never a guess
//  - credits are a ledger, never a mutable counter: the balance is derivable and auditable
//  - failed builds are recorded but NEVER charged

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id               String   @id @default(cuid())
  email            String   @unique
  // Nullable because a Google-only account never sets a local password.
  passwordHash     String?
  googleId         String?  @unique
  name             String?
  role             String   @default("CUSTOMER") // CUSTOMER | ADMIN
  stripeCustomerId String?
  createdAt        DateTime @default(now())

  // Self-imposed ceiling on credits spent per rolling 30 days. NULL = no cap.
  // This is the user's own guard against a runaway session, not a plan limit —
  // bill shock is the category's deepest trust wound (one competitor billed
  // $607 against a $25 plan in three days), and a cap the user sets themselves
  // is the cheapest honest answer to it.
  spendCapCredits Int?

  sessions     Session[]
  projects     Project[]
  ledger       CreditLedger[]
  events       Event[]
  supportNotes SupportNote[]
}

// First-party analytics. Self-hosted deliberately: cheaper, keeps the data
// ours, avoids another paid API on the critical path, and is privacy-clean.
//
// One wide table rather than a table per dashboard, because the activation
// funnel, retention cohorts, per-user journey, attribution and the overview
// tiles are all different queries over the same stream. Build it once, or
// every dashboard invents its own tracking.
model Event {
  id     String  @id @default(cuid())
  // Nullable so pre-signup events (landing view, prompt submitted) still land.
  userId String?
  /// Dotted, past-tense name — see EVENTS in lib/events.ts. Never free text.
  name   String
  /// Small, non-PII payload: ids, counts, enum-ish strings. Never prompt bodies.
  props  Json?

  createdAt DateTime @default(now())

  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)

  // Funnels scan by name over a window; journeys scan one user over a window.
  @@index([name, createdAt])
  @@index([userId, createdAt])
}

// Who did what in the admin panel. Admin surfaces read cost, margin, customer
// prompts and personal data; without a log, "who looked at this account" has no
// answer. Append-only by convention — nothing in the app updates or deletes a row.
model AdminAuditLog {
  id         String   @id @default(cuid())
  /// The admin who acted. Kept as a plain id, not a relation, so the record
  /// survives that admin's account being deleted.
  actorId    String
  actorEmail String
  /// Dotted, past-tense: "user.viewed", "site.taken_down", "flag.changed".
  action     String
  targetType String?
  targetId   String?
  /// Small, non-PII context. Never prompt bodies or generated content.
  meta       Json?
  createdAt  DateTime @default(now())

  @@index([actorId, createdAt])
  @@index([action, createdAt])
  @@index([targetType, targetId])
}

// Runtime kill switches and gradual rollout. Deliberately a table rather than
// env vars: flipping a flag must not require a deploy, which is the entire
// point of having a kill switch.
model FeatureFlag {
  key         String   @id
  enabled     Boolean  @default(false)
  description String   @default("")
  /// 0-100. Ignored when `enabled` is false. Bucketed by user id so a given
  /// user's answer is stable rather than flickering between requests.
  rolloutPct  Int      @default(100)
  updatedAt   DateTime @updatedAt
  updatedBy   String?
}

// One row per moderation finding per publish attempt. Sub-blocking findings
// previously went only to console.warn — enough to reconstruct one site after
// it is reported, not enough to query proactively, and not enough to ever
// measure the false-positive rate that gates promoting a rule to blocking.
model ModerationFinding {
  id        String   @id @default(cuid())
  projectId String
  rule      String
  severity  String // high | medium | low
  path      String
  evidence  String
  /// "blocked" when this finding stopped the publish, "recorded" otherwise.
  action    String
  createdAt DateTime @default(now())

  reviewedAt DateTime?
  reviewedBy String?
  /// Set on review: "true_positive" | "false_positive".
  outcome    String?

  @@index([projectId, createdAt])
  @@index([severity, createdAt])
  @@index([rule, createdAt])
}

// Operator-written notes about a customer, for support continuity. Never shown
// to the customer, so it must never be used to store anything we would not
// stand behind if disclosed in a data-subject access request.
model SupportNote {
  id          String   @id @default(cuid())
  userId      String
  authorEmail String
  body        String
  createdAt   DateTime @default(now())

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId, createdAt])
}

// Every processed Stripe webhook event, keyed by Stripe's own event id.
// This is the idempotency guard: a webhook retry (Stripe resends on any
// non-2xx or timeout) must never grant credits twice for the same payment.
model StripeEvent {
  id        String   @id
  type      String
  createdAt DateTime @default(now())
}

model Session {
  id        String   @id @default(cuid())
  userId    String
  tokenHash String   @unique
  expiresAt DateTime
  createdAt DateTime @default(now())

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId])
}

model Project {
  id        String   @id @default(cuid())
  userId    String
  name      String
  slug      String   @unique // becomes <slug>.kodely.site when published
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  publishedAt DateTime?

  user     User          @relation(fields: [userId], references: [id], onDelete: Cascade)
  files    ProjectFile[]
  messages Message[]
  builds   Build[]

  @@index([userId])
}

// The working tree of a generated project. `published` files are the live
// snapshot served on the public subdomain; draft files are what the preview shows.
// `kind` separates the two file universes that live in this one table:
// "source" is the real Vite+React+TS project the agent edits (never served
// directly — a browser can't run raw .tsx); "build" is the compiled static
// output (lib/build-site.ts) that preview/publish/site-serving actually read.
model ProjectFile {
  id        String   @id @default(cuid())
  projectId String
  path      String
  content   String
  published Boolean  @default(false)
  kind      String   @default("source") // "source" | "build"
  updatedAt DateTime @updatedAt

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)

  @@unique([projectId, path, published, kind])
  @@index([projectId])
}

model Message {
  id        String   @id @default(cuid())
  projectId String
  role      String // user | assistant
  content   String
  createdAt DateTime @default(now())

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)

  @@index([projectId])
}

model Build {
  id        String    @id @default(cuid())
  projectId String
  status    String    @default("RUNNING") // RUNNING | SUCCEEDED | FAILED
  model     String
  prompt    String
  error     String?
  createdAt DateTime  @default(now())
  endedAt   DateTime?

  inputTokens      Int @default(0)
  outputTokens     Int @default(0)
  cacheReadTokens  Int @default(0)
  cacheWriteTokens Int @default(0)
  filesWritten     Int @default(0)

  // How many times the build had to be repaired before it compiled. 0 means it
  // compiled first try. This is the instrument for "green-build-first-try",
  // which the roadmap names as a kill-criterion gating the jump to backend
  // work — and which, until now, nothing measured. Retries are also the
  // clearest early signal of prompt or model regressions.
  repairAttempts Int @default(0)

  // Full draft file tree AFTER this build finished, as {path: content}. Small
  // sites, so a JSON snapshot per successful build is cheap and makes rollback
  // a plain restore instead of needing per-file version history.
  filesSnapshot Json?

  // Real model spend in micro-dollars, and what we actually charged.
  costMicros     Int @default(0)
  creditsCharged Int @default(0)

  project Project        @relation(fields: [projectId], references: [id], onDelete: Cascade)
  ledger  CreditLedger[]

  @@index([projectId])
}

model CreditLedger {
  id          String   @id @default(cuid())
  userId      String
  delta       Int // negative = spend, positive = grant/refund
  reason      String
  buildId     String?
  balanceAfter Int
  createdAt   DateTime @default(now())

  user  User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  build Build? @relation(fields: [buildId], references: [id], onDelete: SetNull)

  @@index([userId])
}

// SEO content pages (comparisons, guides, use-cases, glossary, feature pages,
// personas — see the "SEO · *" board columns). bodyHtml is pre-rendered,
// hand-authored semantic HTML, not user input or markdown rendered at
// runtime — there's no templating/interpolation risk serving it directly.
model BlogPost {
  id              String   @id @default(cuid())
  slug            String   @unique
  title           String
  metaDescription String
  category        String // matches the board column, e.g. "Comparisons", "Guides"
  targetKeyword   String
  bodyHtml        String
  publishedAt     DateTime @default(now())
  updatedAt       DateTime @updatedAt

  @@index([category])
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { MICROS_PER_CREDIT, spentInWindow } from "@/lib/credits";
import {
  Empty,
  Panel,
  StatTile,
  TableFrame,
  Th,
  formatDateTime,
  formatUsd,
  reasonLabel,
  statusClass,
  truncate,
} from "../ui";

export const dynamic = "force-dynamic";

// Bounded reads. A support question is answered from the recent tail, and an
// unbounded findMany on a heavy account would be the one slow query on this
// panel. Each table says so when it is showing a truncated view.
const LEDGER_LIMIT = 250;
const BUILD_LIMIT = 100;
const EVENT_LIMIT = 100;

function propsSummary(props: unknown): string {
  if (props === null || typeof props !== "object" || Array.isArray(props)) return "";
  return Object.entries(props as Record<string, unknown>)
    .map(([k, v]) => `${k}=${typeof v === "string" ? v : JSON.stringify(v)}`)
    .join("  ·  ");
}

export default async function AdminUserDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  // Defense in depth — see app/admin/page.tsx. The layout gate is the primary
  // one, but a layout must not be the sole authorization boundary.
  if (!(await getAdminUser())) notFound();

  const { id } = await params;

  const user = await db.user.findUnique({
    where: { id },
    select: {
      id: true,
      email: true,
      name: true,
      role: true,
      createdAt: true,
      spendCapCredits: true,
      googleId: true,
      passwordHash: true,
      stripeCustomerId: true,
    },
  });
  if (!user) notFound();

  const [
    projects,
    builds,
    ledger,
    events,
    buildTotals,
    buildStatuses,
    grantedAgg,
    spentAgg,
    ledgerTotal,
    buildTotal,
    eventTotal,
    windowSpend,
  ] = await Promise.all([
    db.project.findMany({
      where: { userId: id },
      orderBy: { createdAt: "desc" },
      select: {
        id: true,
        name: true,
        slug: true,
        createdAt: true,
        updatedAt: true,
        publishedAt: true,
        _count: { select: { builds: true, files: true, messages: true } },
      },
    }),
    db.build.findMany({
      where: { project: { userId: id } },
      orderBy: { createdAt: "desc" },
      take: BUILD_LIMIT,
      select: {
        id: true,
        createdAt: true,
        endedAt: true,
        status: true,
        model: true,
        inputTokens: true,
        outputTokens: true,
        costMicros: true,
        creditsCharged: true,
        repairAttempts: true,
        prompt: true,
        error: true,
        project: { select: { id: true, name: true } },
      },
    }),
    db.creditLedger.findMany({
      where: { userId: id },
      // Same ordering as lib/credits.ts getBalance, with `id` as a stable
      // tiebreak — so row 0 here IS the row that defines the balance.
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      take: LEDGER_LIMIT,
      select: {
        id: true,
        createdAt: true,
        delta: true,
        reason: true,
        balanceAfter: true,
        build: { select: { id: true, status: true, project: { select: { name: true } } } },
      },
    }),
    db.event.findMany({
      where: { userId: id },
      // Served straight off the @@index([userId, createdAt]) on Event.
      orderBy: { createdAt: "desc" },
      take: EVENT_LIMIT,
      select: { id: true, name: true, props: true, createdAt: true },
    }),
    db.build.aggregate({
      where: { project: { userId: id } },
      _sum: { costMicros: true, creditsCharged: true },
    }),
    db.build.groupBy({
      by: ["status"],
      where: { project: { userId: id } },
      _count: { _all: true },
    }),
    db.creditLedger.aggregate({ where: { userId: id, delta: { gt: 0 } }, _sum: { delta: true } }),
    db.creditLedger.aggregate({ where: { userId: id, delta: { lt: 0 } }, _sum: { delta: true } }),
    db.creditLedger.count({ where: { userId: id } }),
    db.build.count({ where: { project: { userId: id } } }),
    db.event.count({ where: { userId: id } }),
    // Reused straight from lib/credits.ts so the number shown here is the
    // same one the spend cap actually enforces — a reimplementation that
    // drifted would make this page lie about why someone was blocked.
    spentInWindow(id),
  ]);

  const balance = ledger[0]?.balanceAfter ?? 0;
  const granted = grantedAgg._sum.delta ?? 0;
  const spent = Math.abs(spentAgg._sum.delta ?? 0);

  const costMicros = buildTotals._sum.costMicros ?? 0;
  const creditsCharged = buildTotals._sum.creditsCharged ?? 0;
  const revenueMicros = creditsCharged * MICROS_PER_CREDIT;
  const marginMicros = revenueMicros - costMicros;

  const succeeded = buildStatuses.find((s) => s.status === "SUCCEEDED")?._count._all ?? 0;
  const failed = buildStatuses.find((s) => s.status === "FAILED")?._count._all ?? 0;

  // ── Integrity checks, computed from rows already in hand ────────────────
  // The ledger is append-only and starts at zero, so balanceAfter must be the
  // running sum of every delta. Walk the fetched window oldest-first; only
  // anchor on the very first row when the whole ledger is on the page.
  const chrono = [...ledger].reverse();
  const brokenRows = new Set<string>();
  if (chrono.length > 0 && ledgerTotal <= LEDGER_LIMIT && chrono[0].balanceAfter !== chrono[0].delta) {
    brokenRows.add(chrono[0].id);
  }
  for (let i = 1; i < chrono.length; i++) {
    if (chrono[i - 1].balanceAfter + chrono[i].delta !== chrono[i].balanceAfter) {
      brokenRows.add(chrono[i].id);
    }
  }

  // The anti-bill-shock contract: a build that FAILED is recorded with its
  // true cost and charged ZERO. Anything else is a refund waiting to happen,
  // and is the literal subject of "my build failed and I was charged".
  const chargedFailures = builds.filter((b) => b.status !== "SUCCEEDED" && b.creditsCharged > 0);
  const chargesOnBadBuilds = ledger.filter(
    (l) => l.build !== null && l.delta < 0 && l.build.status !== "SUCCEEDED",
  );

  const maxBalance = Math.max(1, ...ledger.map((l) => l.balanceAfter));
  const capRemaining =
    user.spendCapCredits === null ? null : Math.max(0, user.spendCapCredits - windowSpend);

  const signInMethods = [
    user.passwordHash ? "password" : null,
    user.googleId ? "google" : null,
  ].filter(Boolean);

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin/users"
          className="text-xs text-black/50 underline-offset-4 hover:underline dark:text-white/50"
        >
          ← Users
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">{user.email}</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          {user.name ? `${user.name} · ` : ""}
          {user.role} · signed up {formatDateTime(user.createdAt)} ·{" "}
          {signInMethods.length > 0 ? signInMethods.join(" + ") : "no sign-in method"}
          {user.stripeCustomerId ? " · stripe customer" : ""}
        </p>
        <p className="mt-1 font-mono text-xs text-black/40 dark:text-white/40">{user.id}</p>
      </div>

      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-6">
        <StatTile
          label="Credit balance"
          value={<span className={balance === 0 ? "text-red-600 dark:text-red-400" : ""}>{balance}</span>}
          hint={
            user.spendCapCredits === null
              ? "no spend cap set"
              : `cap ${user.spendCapCredits}/30d · ${capRemaining} left`
          }
        />
        <StatTile label="Lifetime granted" value={granted} />
        <StatTile label="Lifetime spent" value={spent} hint={`${windowSpend} in last 30d`} />
        <StatTile
          label="Builds"
          value={
            <>
              <span className="text-emerald-600 dark:text-emerald-400">{succeeded}</span>
              <span className="text-black/30 dark:text-white/30"> / </span>
              <span className="text-red-600 dark:text-red-400">{failed}</span>
            </>
          }
          hint={`${buildTotal} total`}
        />
        <StatTile
          label="Imputed cost"
          value={formatUsd(costMicros, 4)}
          hint={`${creditsCharged} credits charged`}
        />
        <StatTile
          label="Margin"
          value={formatUsd(marginMicros, 4)}
          hint="credits charged at list, minus real spend"
        />
      </div>

      {(chargedFailures.length > 0 || chargesOnBadBuilds.length > 0 || brokenRows.size > 0) && (
        <div className="mb-8 rounded-xl border border-amber-500/40 bg-amber-500/5 p-5 text-sm">
          <h2 className="text-sm font-medium text-amber-700 dark:text-amber-500">Needs a look</h2>
          <ul className="mt-2 list-disc space-y-1 pl-5 text-black/70 dark:text-white/70">
            {chargedFailures.length > 0 && (
              <li>
                {chargedFailures.length} build(s) in the recent window were charged despite not
                succeeding. Failed builds are never supposed to be billed.
              </li>
            )}
            {chargesOnBadBuilds.length > 0 && (
              <li>
                {chargesOnBadBuilds.length} ledger charge(s) point at a build that is not in
                SUCCEEDED state.
              </li>
            )}
            {brokenRows.size > 0 && (
              <li>
                {brokenRows.size} ledger row(s) have a balanceAfter that does not equal the running
                sum of deltas. Marked with ! in the statement below.
              </li>
            )}
          </ul>
        </div>
      )}

      <div className="mb-8">
        <Panel
