  formatDateTime,
  severityClass,
  siteHost,
  truncate,
} from "./ui";

export const dynamic = "force-dynamic";

const PAGE_SIZE = 25;

// ── Caps ──────────────────────────────────────────────────────────────────
// Two of the views filter Project by an id set assembled from another table.
// Both sets are small by nature — a flagged site is the exception, a taken-down
// site more so — but "small by nature" is not a bound, and an unbounded IN ()
// list is how a page like this dies quietly a year from now. Each cap is
// surfaced in the UI when it actually bites, rather than silently truncating.
const FLAGGED_SITE_CAP = 2000;
const TAKEN_DOWN_CAP = 2000;

type View = "live" | "flagged" | "down";

const VIEWS: Record<View, { label: string; blurb: string }> = {
  live: {
    label: "Live",
    blurb: "Every project with publishedAt set — the sites currently resolving on *.kodely.site.",
  },
  flagged: {
    label: "Needs review",
    blurb: "Live sites carrying at least one moderation finding nobody has ruled on yet.",
  },
  down: {
    label: "Taken down",
    blurb:
      "Projects an operator took offline from this panel and which are still offline. Read out of AdminAuditLog — publishedAt alone cannot tell a takedown from a site that was never published.",
  },
};

function isView(v: unknown): v is View {
  return typeof v === "string" && v in VIEWS;
}

type SortKey = "recent" | "oldest" | "slug" | "updated";

/**
 * DATABASE-NATIVE sorts only, for the same reason app/admin/users/page.tsx
 * gives: finding count, file count and last build are all rolled up per PAGE
 * from other tables, so offering "sort by findings" would sort 25 arbitrary
 * rows and look like it had sorted the registry. The "Needs review" view is the

 * answers 404 for every path — pages, assets, and the synthesised robots.txt
 * and sitemap.xml alike — the moment it is null, and proxy.ts rewrites
 * <slug>.kodely.site into that route with no state of its own. Nothing else is
 * consulted.
 *
 * Nothing is deleted. The published file rows stay exactly where they are, the
 * draft tree is untouched, and the project keeps its slug — so the owner still
 * has all of their work and can republish it themselves from the project page.
 */
export async function takeDownSite(formData: FormData): Promise<void> {
  const admin = await getAdminUser();
  if (!admin) notFound();

  const projectId = String(formData.get("projectId") ?? "");
  const confirmSlug = String(formData.get("confirmSlug") ?? "").trim();
  const reason = String(formData.get("reason") ?? "");
  if (!projectId) notFound();

  const project = await db.project.findUnique({
    where: { id: projectId },
    select: { id: true, slug: true, userId: true, publishedAt: true },
  });
  if (!project) notFound();

  // Already offline — someone took it down in another tab, or the owner never
  // republished. Not an error, just nothing left to do.
  if (!project.publishedAt) {
    redirect(`/admin/sites/${projectId}?takedown=already`);
  }

  if (!TAKEDOWN_REASONS[reason]) {
    redirect(`/admin/sites/${projectId}/takedown?error=reason`);
  }

  // The confirmation step. Typing the slug is the whole guard against taking
  // down the wrong site from a list of near-identical rows, so it is checked
  // HERE and not only in the browser.
  if (confirmSlug !== project.slug) {
    redirect(`/admin/sites/${projectId}/takedown?error=slug`);
  }

  await db.$transaction([
    db.project.update({ where: { id: projectId }, data: { publishedAt: null } }),
    // Append-only, and written in the same transaction as the takedown so a
    // site can never go dark with no record of who darkened it. "site.taken_down"
    // is the action name the AdminAuditLog model itself gives as an example.
    db.adminAuditLog.create({
      data: {
        actorId: admin.id,
        actorEmail: admin.email,
        action: "site.taken_down",
        targetType: "project",
        targetId: projectId,
        meta: {
          slug: project.slug,
          ownerId: project.userId,
          reason,
          // What the site's live-since timestamp was, since the column that
          // held it is about to be null.
          publishedAt: project.publishedAt.toISOString(),
        },
      },
    }),
  ]);

  revalidatePath(`/admin/sites/${projectId}`);
  revalidatePath("/admin/sites");
  redirect(`/admin/sites/${projectId}?takedown=done`);
}
