// ── Vocabulary ────────────────────────────────────────────────────────────
//
// Same discipline as EVENTS in lib/events.ts: every name here must have a real
// emitter, because a name nobody fires makes the log describe oversight that
// isn't happening. That rule is applied strictly, in two directions:
//
//   * `audit_log.viewed` is emitted today, by app/admin/audit/page.tsx.
//   * The other three are declared but not yet emitted ONLY because their
//     pages are owned elsewhere and could not be edited in this change. Each
//     one names the exact file that owes it a one-line call — this is a work
//     order with a deadline, not an aspiration, and the list is short enough
//     to notice if it stops shrinking.
//
// Notably ABSENT: names for mutating actions such as "site.taken_down" or
// "flag.changed". Kodely has no takedown surface and no feature-flag admin UI
// (the FeatureFlag model exists but nothing reads or writes it). Declaring
// names for capabilities that do not exist is exactly the mistake lib/events.ts
// documents having already made once. Add those names in the same change that
// adds the button.
export const ADMIN_ACTIONS = {
  /** Cost and margin overview, plus 50 recent builds with customer prompts.
   *  Owed by: app/admin/page.tsx */
  dashboardViewed: "dashboard.viewed",
  /** A page of the customer list: emails, names, balances, lifetime spend.
   *  Owed by: app/admin/users/page.tsx */
  userListViewed: "user_list.viewed",
  /** One customer's full record: billing statement, projects, build history
   *  with prompts, event journey.
   *  Owed by: app/admin/users/[id]/page.tsx */
  userViewed: "user.viewed",
  /** This log itself. Reading the accountability record is an access worth
   *  recording — it is how you would notice someone checking whether their own
   *  browsing had been noticed. Emitted by: app/admin/audit/page.tsx */
  auditLogViewed: "audit_log.viewed",
} as const;

export type AdminAction = (typeof ADMIN_ACTIONS)[keyof typeof ADMIN_ACTIONS];

/** Human labels for the log UI. Keyed by the union, so adding an action to
 *  ADMIN_ACTIONS without labelling it is a type error rather than a blank cell. */
export const ADMIN_ACTION_LABELS: Record<AdminAction, string> = {
  "dashboard.viewed": "Viewed cost dashboard",
  "user_list.viewed": "Viewed customer list",
