// ── Vocabulary ────────────────────────────────────────────────────────────
//
// What belongs in the log, stated once so the list below is derivable rather
// than a matter of taste:
//
//   * EVERY WRITE an admin makes, without exception.
//   * EVERY READ of a surface that exposes CUSTOMER data — accounts, prompts,
//     billing, feedback, support notes, published sites.
//
// and, by the same rule, what does not: /admin/flags shows kill switches and
// rollout percentages, which are our data, not a customer's. Its writes are
// recorded (flag.changed, flag.deleted); merely looking at it is not. A log
// that records everything indiscriminately is one nobody reads.
//
// Same discipline as EVENTS in lib/events.ts — a name nobody fires makes the
// log describe oversight that is not happening — but applied with one
// deliberate difference, because this vocabulary has a second job: it is the
// coordination point for admin surfaces owned by other people. So names are
// admitted here only when the SURFACE ALREADY EXISTS in the tree, and each one
// carries the exact file that owes it the call. Two are being written today;
// the rest are a work order, and the panel itself shows the outstanding list
// (see countAdminActions) so it stays visible after this comment is forgotten.
export const ADMIN_ACTIONS = {
  // ── Recorded today ──
  /** A published site was taken offline (publishedAt cleared). Written inside
   *  the same transaction as the takedown, which is why it does not go through
   *  recordAdminAction — see adminActionRow below.
   *  Emitted by: app/admin/sites/actions.ts */
  siteTakenDown: "site.taken_down",
  /** This log itself. Reading the accountability record is an access worth
   *  recording — it is how you would notice someone checking whether their own
   *  browsing had been noticed.
   *  Emitted by: app/admin/audit/page.tsx */
  auditLogViewed: "audit_log.viewed",

  // ── Owed: reads of customer data ──
  /** Cost and margin overview, plus 50 recent builds with customer prompts.
   *  Owed by: app/admin/page.tsx */
  dashboardViewed: "dashboard.viewed",
  /** A page of the customer list: emails, names, balances, lifetime spend.
   *  Owed by: app/admin/users/page.tsx */
  userListViewed: "user_list.viewed",
  /** One customer's full record: billing statement, projects, build history
   *  with prompts, event journey.
   *  Owed by: app/admin/users/[id]/page.tsx */
  userViewed: "user.viewed",
